class Counter(scope: CoroutineScope) {
    private val mailbox = Channel<Int>(capacity = 64)   // bounded mailbox
    private var count = 0
    init { scope.launch { for (delta in mailbox) count += delta } }  // one at a time
    suspend fun tell(delta: Int) = mailbox.send(delta)  // suspends when full
}
